function renderProgressiveFunnel(x){
 const observations=(x.sessions||[]).flatMap(s=>s.observations||[]);
 const retrieved=observations.length;
 const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v};
 set("f-provider","TIDAK_TERSEDIA");
 set("f-retrieved",retrieved);
 set("f-remaining","TIDAK_TERSEDIA");
 set("f-dedup",retrieved?"TIDAK_TERCATAT":"NOT_RUN");
 set("f-screened",retrieved?"TIDAK_TERCATAT":"NOT_RUN");
 set("f-human",retrieved?"TIDAK_TERCATAT":"NOT_RUN");
 set("f-project","TIDAK_TERSEDIA");
}

