function titleTerms(title){return [...new Set((String(title||"").toLowerCase().match(/[a-z][a-z-]{2,}/g)||[]).filter(x=>!drillStop.has(x)))];}
function computeSubareas(members,path){const counts=new Map(),chosen=new Set(path);for(const m of members){const p=trialPaperMap.get(m.openalex_id)||m;for(const term of titleTerms(p.title))if(!chosen.has(term))counts.set(term,(counts.get(term)||0)+1);}return [...counts].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0])).filter(([,n])=>n>=3).slice(0,20);}

